console.log(`Starting compilation of 1,000+ TOEIC vocabulary words...`);

// สร้าง Set ป้องกันคำซ้ำ
const seenWords = new Set();
const compiledList = [];

// 1. เพิ่มคำศัพท์กลุ่มแรก (360 คำหลัก จาก 12 หมวด x 30 คำ)
let idCounter = 1;

for (const group of rawVocabGroups) {
  for (const item of group.items) {
    const [word, pos, meaningTh, exampleEn, manaCost] = item;
    const cleanWord = word.trim();
    const wordKey = cleanWord.toLowerCase();
    if (!seenWords.has(wordKey)) {
      seenWords.add(wordKey);
      const id = `card-${String(idCounter++).padStart(4, '0')}`;
      compiledList.push({
        id,
        word: cleanWord,
        partOfSpeech: pos,
        meaningTh,
        exampleEn,
        category: group.category,
        manaCost: Number(manaCost) || 2
      });
    }
  }
}

// 2. เพิ่มคำศัพท์จาก highFrequencyToeicWords
for (const item of highFrequencyToeicWords) {
  const [word, pos, meaningTh, exampleEn, cat, manaCost] = item;
  const cleanWord = word.trim();
  const wordKey = cleanWord.toLowerCase();
  if (!seenWords.has(wordKey)) {
    seenWords.add(wordKey);
    const id = `card-${String(idCounter++).padStart(4, '0')}`;
    compiledList.push({
      id,
      word: cleanWord,
      partOfSpeech: pos,
      meaningTh,
      exampleEn,
      category: cat || 'Corporate',
      manaCost: Number(manaCost) || 2
    });
  }
}

