for (const item of vocabBankG_to_Z) {
  const [word, pos, meaningTh, exampleEn, cat, manaCost] = item;
  const cleanWord = word.trim();
  const wordKey = cleanWord.toLowerCase();
  if (!seenWords.has(wordKey)) {
    seenWords.add(wordKey);
    const id = `card-${String(idCounter++).padStart(4, '0')}`;
    compiledList.push({
      id,
      word: cleanWord,
      partOfSpeech: pos,
      meaningTh,
      exampleEn,
      category: cat || 'Corporate',
      manaCost: Number(manaCost) || 2
    });
  }
}

